const body = $input.first().json.body || $input.first().json;
const question = body.question;
if (!question || question.trim() === '') {
  throw new Error('Pole "question" objazatelno');
}
return [{
  json: {
    question: question.trim(),
    subject: body.subject || null,
    grade: body.grade || null,
    top_k: body.top_k || 5,
    llm: body.llm || 'local'
  }
}];

const queryData = $('2. Validation').first().json;
const embedResponse = $input.first().json;
let embedding = embedResponse.embedding;
if (!embedding) throw new Error('Failed to get embedding');
const embeddingStr = '[' + embedding.join(',') + ']';

const subjectVal = queryData.subject ? "'" + queryData.subject.replace(/'/g, "''") + "'" : 'NULL';
const gradeVal = queryData.grade ? String(parseInt(queryData.grade)) : 'NULL';

return [{
  json: {
    question: queryData.question,
    subject: queryData.subject,
    grade: queryData.grade,
    top_k: queryData.top_k,
    llm: queryData.llm,
    query_embedding: embeddingStr,
    subject_val: subjectVal,
    grade_val: gradeVal
  }
}];

const question = $('2. Validation').first().json.question;
const llm = $('4. Prepare').first().json.llm;
const results = $input.all();

let lang = 'ro';
if (/[\u0400-\u04FF]/.test(question)) lang = 'ru';
else if (/^(what|who|where|when|why|how|is|are|do|does|can|could)/i.test(question)) lang = 'en';

const langInstructions = {
  'ru': 'VAZHNO: Otvechaj TOLKO na russkom jazyke!',
  'en': 'IMPORTANT: Answer ONLY in English!',
  'ro': 'Raspunde in limba romana.'
};

let context = '';
let sources = [];
results.forEach((item, i) => {
  const doc = item.json;
  context += `[Source ${i+1}: ${doc.title || doc.book_id}]\n${doc.content}\n\n`;
  sources.push({
    title: doc.title || doc.book_id,
    subject: doc.subject,
    similarity: doc.similarity ? Number(doc.similarity).toFixed(2) : 'N/A'
  });
});

const systemPrompt = 'You are an educational assistant EDU RAG. ' + langInstructions[lang] + ' Answer ONLY based on the provided context. Cite sources.';

return [{
  json: { question, context, sources, lang, llm, systemPrompt }
}];

